package com.vision.iptv;
import java.io.*;import java.net.*;import java.util.*;import java.text.*;import java.util.zip.GZIPInputStream;import android.util.Xml;import org.xmlpull.v1.XmlPullParser;
final class Epg {
 static class Programme {String title="",description="";long start,end;}
 final Map<String,List<Programme>> entries=new HashMap<>();
 private static final ThreadLocal<SimpleDateFormat[]> DATE_FORMATS=new ThreadLocal<SimpleDateFormat[]>(){protected SimpleDateFormat[] initialValue(){SimpleDateFormat a=new SimpleDateFormat("yyyyMMddHHmmss",Locale.US),b=new SimpleDateFormat("yyyyMMddHHmmss Z",Locale.US);for(SimpleDateFormat f:new SimpleDateFormat[]{a,b}){f.setTimeZone(TimeZone.getTimeZone("UTC"));f.setLenient(false);}return new SimpleDateFormat[]{a,b};}};
 static long time(String value){if(value==null)return 0;try{String s=value.trim();return DATE_FORMATS.get()[s.length()>14?1:0].parse(s).getTime();}catch(Exception e){return 0;}}
 private static String cap(String s,int max){return s.length()>max?s.substring(0,max):s;}
 private static void interrupted()throws IOException{if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("EPG cancelled");}
 private static boolean wanted(Set<String> ids,String id){return ids==null||ids.isEmpty()||ids.contains(id);}
 private void sort(){for(List<Programme> l:entries.values())l.sort(Comparator.comparingLong(x->x.start));}
 static Epg readCache(File file)throws Exception{return readCache(file,null,false);}

 static File cacheFile(File dir,String address)throws Exception{byte[] hash=java.security.MessageDigest.getInstance("SHA-256").digest(address.getBytes(java.nio.charset.StandardCharsets.UTF_8));StringBuilder name=new StringBuilder("epg_");for(byte b:hash)name.append(String.format(Locale.US,"%02x",b&255));return new File(dir,name+".bin");}
 static Epg readCache(File file,Set<String> ids,boolean economical)throws Exception{if(!file.isFile()||file.length()>48L*1024*1024||System.currentTimeMillis()-file.lastModified()>604800000L)return null;Epg result=new Epg();try(DataInputStream in=new DataInputStream(new BufferedInputStream(new FileInputStream(file)))){if(in.readInt()!=0x45504731)return null;int n=in.readInt();if(n<0||n>300000)throw new IOException("Invalid cache");long now=System.currentTimeMillis();for(int i=0;i<n;i++){if((i&255)==0)interrupted();String id=in.readUTF();Programme p=new Programme();p.start=in.readLong();p.end=in.readLong();p.title=cap(in.readUTF(),256);String desc=in.readUTF();p.description=economical?"":cap(desc,1024);if(wanted(ids,id)&&p.end>now-604800000L&&p.start<now+604800000L)result.entries.computeIfAbsent(id,k->new ArrayList<>()).add(p);}}result.sort();return result;}
 void writeCache(File file)throws Exception{File tmp=File.createTempFile("epg_",".tmp",file.getParentFile());try{try(DataOutputStream out=new DataOutputStream(new BufferedOutputStream(new FileOutputStream(tmp)))){out.writeInt(0x45504731);int n=0;for(List<Programme> l:entries.values())n+=l.size();out.writeInt(n);for(Map.Entry<String,List<Programme>> e:entries.entrySet())for(Programme p:e.getValue()){out.writeUTF(e.getKey());out.writeLong(p.start);out.writeLong(p.end);out.writeUTF(p.title.substring(0,Math.min(2000,p.title.length())));out.writeUTF(p.description.substring(0,Math.min(4000,p.description.length())));}}if(tmp.length()>48L*1024*1024)return;if(!tmp.renameTo(file))throw new IOException("Cache rename failed");File[] old=file.getParentFile().listFiles((d,n)->n.startsWith("epg_")&&n.endsWith(".bin")&&!n.equals(file.getName()));if(old!=null)for(File x:old)x.delete();}finally{tmp.delete();}}
 static Epg load(String address)throws Exception{return load(address,null,false);}
 static Epg load(String address,Set<String> ids,boolean economical)throws Exception{URL url=new URL(address);if(!url.getProtocol().equals("http")&&!url.getProtocol().equals("https"))throw new IOException("HTTP(S) only");HttpURLConnection c=NetworkPolicy.open(url,15000,30000,"VisionIPTV/1.0",false,null);Epg epg=new Epg();try(BufferedInputStream raw=new BufferedInputStream(c.getInputStream())){raw.mark(2);int a=raw.read(),b=raw.read();raw.reset();InputStream in=a==31&&b==139?new GZIPInputStream(raw):raw;XmlPullParser p=Xml.newPullParser();p.setInput(in,null);Programme item=null;String channel=null;long now=System.currentTimeMillis();int count=0;for(int event=p.getEventType();event!=XmlPullParser.END_DOCUMENT;event=p.next()){interrupted();if(event==XmlPullParser.START_TAG){String tag=p.getName();if(tag.equals("programme")){channel=p.getAttributeValue(null,"channel");item=null;if(channel!=null&&wanted(ids,channel)){long start=time(p.getAttributeValue(null,"start")),end=time(p.getAttributeValue(null,"stop"));if(start>0&&end>start&&end>now-604800000L&&start<now+604800000L){item=new Programme();item.start=start;item.end=end;}}}else if(item!=null&&tag.equals("title"))item.title=cap(p.nextText(),256);else if(item!=null&&tag.equals("desc")&&!economical)item.description=cap(p.nextText(),1024);}else if(event==XmlPullParser.END_TAG&&p.getName().equals("programme")&&item!=null){if(channel!=null&&item.end>now-604800000L&&item.start<now+604800000L){epg.entries.computeIfAbsent(channel,k->new ArrayList<>()).add(item);if(++count>300000)throw new IOException("EPG too large");}item=null;}}}finally{c.disconnect();}epg.sort();return epg;}
 List<Programme> forChannel(String id){return entries.getOrDefault(id,Collections.emptyList());}
 Programme current(String id){long now=System.currentTimeMillis();List<Programme> l=forChannel(id);int lo=0,hi=l.size();while(lo<hi){int mid=(lo+hi)>>>1;if(l.get(mid).start<=now)lo=mid+1;else hi=mid;}for(int i=lo-1;i>=0;i--){Programme p=l.get(i);if(p.end>now)return p;if(now-p.start>86400000L)break;}return null;}
}